#pragma once

#include <cstdint>
#include <string>
#include <vector>

#include "problems/Problem.hpp"

namespace algosearch {

// Section 134: ten integer problems in the style of PSB1 (Helmuth and Spector, GECCO 2015), chosen before the pieces of
// sections 126-131 were tried on them. The PSB1 datasets are generated by code, not downloaded, so the instance
// generators and the references here are mine, written from the PSB1 problem descriptions (the input ranges are the
// PSB1 ones as I remember them, not checked against the original generator). A run gets 200 training cases (a few edge
// cases, then random) and is judged on 2,000 unseen random cases, as in section 126. The program reads `arr` and
// writes its answer at the front.
//   last_index_of_zero: arr = a vector in [-50, 50] holding at least one 0; arr[0] = the index of the last 0.
//   count_odds: arr = a vector in [-1000, 1000]; arr[0] = how many items are odd.
//   negative_to_zero: arr = a vector in [-1000, 1000]; the output replaces every negative item by 0 (in place).
//   vectors_summed: arr = a ++ b (equal lengths, [-1000, 1000]); arr[0..L-1] = the item-wise sums.
//   sum_of_squares: arr = {n}, n in 1..100; arr[0] = 1^2 + ... + n^2.
//   collatz_steps: arr = {n}, n in 1..2000; arr[0] = the number of Collatz steps from n to 1.
//   small_or_large: arr = {n}, n in [-10000, 10000]; arr[0] = 1 if n < 1000, 2 if n >= 2000, else 0.
//   mirror_image: arr = a ++ b (equal lengths, [-1000, 1000], half of the cases with b = reverse of a); arr[0] = 1 if
//     b is a reversed, else 0.
//   digits: arr = {n, 0, 0, 0, 0, 0, 0}, n in 1..999999; arr[0..k-1] = the digits of n, last digit first.
//   grade: arr = {A, B, C, D, score}, thresholds A > B > C > D in 0..100; arr[0] = 4 if score >= A, 3 if >= B, 2 if >= C,
//     1 if >= D, else 0.
// Section 137: five more problems for the unseen test of the count-term / square-term options, written before those options were
// run on anything: count_multiples_of_three (vector of 1..8 items in [-20, 20]; arr[0] = how many are multiples of 3),
// even_squares (arr = {n}, n in 1..100; arr[0] = how many k >= 1 have k * k even and k * k < n), sum_of_cubes (arr = {n},
// n in 1..8; arr[0] = 1^3 + ... + n^3), for_loop_index (arr = {start, end, step}, start in 0..20, end in start+1..start+30,
// step in 1..4; arr[0] = the sum of i for i = start, start+step, ... while i < end), smallest4 (arr = 4 items in [-20, 20];
// arr[0] = the minimum).
// Section 135 (medium): section 134 left eight of ten problems at 0/20 because the PSB1 ranges (vectors of up to 50 items in
// [-1000, 1000]) are far harder than the suite's own problems. The medium version, fixed before running, changes only the
// ranges: vectors of 1..8 items; last_index_of_zero in [-5, 5]; count_odds, negative_to_zero, vectors_summed and
// mirror_image in [-20, 20]; sum_of_squares n in 1..10; collatz_steps n in 1..30; small_or_large n in [-100, 100] with the
// thresholds 10 and 20 in place of 1000 and 2000; digits n in 1..9999; grade unchanged. Names: psb1m_<name>.
class Psb1Problem : public Problem {
public:
    enum class Kind {
        LastIndexOfZero, CountOdds, NegativeToZero, VectorsSummed, SumOfSquares, CollatzSteps, SmallOrLarge,
        MirrorImage, Digits, Grade,
        // Section 137, fixed before any run (names psb1n_<name>, one range only, the medium style):
        CountMultiplesOfThree, EvenSquares, SumOfCubes, ForLoopIndex, Smallest4
    };

    // medium = the section 135 version: the same ten problems with small vectors and small values (see below).
    Psb1Problem(Kind kind, int numVars, uint64_t seed, bool medium = false);

    static std::string name(Kind kind);
    static std::vector<int> reference(Kind kind, const std::vector<int>& arr, bool medium = false);
    // One random case of the given kind (the encoded input).
    static std::vector<int> randomInput(Kind kind, class Random& rng, bool medium = false);

    std::vector<Instance> generateInstances(int level) const override { (void)level; return train_; }
    std::string describeLevel(int level) const override;
    int nextLevel(int level) const override { return level + 1; }
    std::vector<Instance> generateAdversarialInstances(int level) const override { (void)level; return test_; }
    bool supportsMagnitudeShift() const override { return false; }
    bool isSolution(const std::vector<int>& input, const std::vector<int>& output) const override;
    double partialScore(const std::vector<int>& input, const std::vector<int>& output) const override;
    int numVars() const override { return numVars_; }
    Instance generateBenchmarkInstance(int n, uint64_t seed) const override;

private:
    Kind kind_;
    bool medium_;
    int numVars_;
    std::vector<Instance> train_, test_;
};

}  // namespace algosearch
